    loop.reset();
    // q <r> c
    assertEquals("q", loop.next());
    // a <r> c
    loop.set("a");
    // a r <c>
    assertEquals("r", loop.next());
    // a b <c>
    loop.set("b");
    // <a> b c
    loop.reset();
    // a <b> c
    assertEquals("a", loop.next());
    // a b <c>
    assertEquals("b", loop.next());
    // <a> b c
    assertEquals("c", loop.next());
}

