    test = MapUtils.putAll(new HashMap<String, String>(), new Object[] { new DefaultMapEntry<>("RED", "#FF0000"), new DefaultMapEntry<>("GREEN", "#00FF00"), new DefaultMapEntry<>("BLUE", "#0000FF") });
